mapper.update:
UPDATE waitlist_entries
SET status = 'CANCELLED',
    updated_at = #{now}
WHERE event_id = #{eventId}
  AND user_id = #{userId}
  AND status IN ('WAITING', 'OFFERED')

UPDATE waitlist_entries entry
SET status = 'FULFILLED',
    updated_at = #{now}
WHERE entry.event_id = #{eventId}
  AND entry.user_id = #{userId}
  AND entry.status = 'OFFERED'
  AND entry.offer_expires_at > #{now}
  AND EXISTS (
      SELECT 1
      FROM waitlist_offer_seats offer_seat
      WHERE offer_seat.entry_id = entry.id
        AND offer_seat.event_seat_id IN

            #{eventSeatId}

  )

mapper.select:
SELECT offer_seat.event_seat_id, entry.user_id
FROM waitlist_entries entry
JOIN waitlist_offer_seats offer_seat ON offer_seat.entry_id = entry.id
WHERE entry.event_id = #{eventId}
  AND entry.status = 'OFFERED'
  AND entry.offer_expires_at > #{now}

SELECT e.id
FROM events e
WHERE e.status = 'PUBLISHED'
  AND e.sales_start_time <= #{now}
  AND e.sales_end_time > #{now}
  AND EXISTS (
      SELECT 1 FROM waitlist_entries entry
      WHERE entry.event_id = e.id AND entry.status = 'WAITING'
  )
ORDER BY (
    SELECT MIN(entry.created_at) FROM waitlist_entries entry
    WHERE entry.event_id = e.id AND entry.status = 'WAITING'
) ASC, e.id ASC
LIMIT #{limit}

SELECT 
FROM waitlist_entries entry
WHERE entry.event_id = #{eventId}
  AND entry.status = 'WAITING'
ORDER BY entry.created_at ASC, entry.id ASC
LIMIT #{limit}

SELECT 
FROM waitlist_entries entry
WHERE entry.status = 'OFFERED'
  AND entry.offer_expires_at <= #{now}
ORDER BY entry.offer_expires_at ASC, entry.id ASC
LIMIT #{limit}

mapper.update:
UPDATE waitlist_entries
SET status = 'EXPIRED',
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'OFFERED'
